INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,1,'Prepare the workspace and tools','Set up a clean, well-lit, flat workspace. Choose the correct tool for assembly and drop it on the Workspace.','Most PC parts use Phillips-head screws.','A clean workspace, a #2 Phillips screwdriver and a parts tray prevent lost screws and damage.','safety',5);
INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=1),'Phillips screwdriver & parts tray','fa-screwdriver-wrench',1,'workspace');
