INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=1),'Side panel (close the case)','fa-square',0,'later');
INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,2,'Observe ESD and electrical safety','Protect components from electrostatic discharge. Place the correct protection in the ESD area.','Think of something worn on the wrist and clipped to bare metal.','An anti-static wrist strap grounded to the case equalizes static charge. Always unplug the PSU while working.','safety',5);
INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=2),'Anti-static wrist strap','fa-hand',1,'esd');
