INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=2),'Monitor','fa-desktop',0,'later');
INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,3,'Prepare the computer case','Open the case so the interior is accessible. Place the right item on the Computer Case.','The side panels must come off first.','Remove the side panels and check the included standoffs, screws and I/O accessories before installing anything.','placement',5);
INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=3),'Case with side panels removed','fa-computer',1,'case');
