INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,4,'Install the processor into the motherboard','Seat the CPU in its socket, matching the gold triangle to the socket marker.','The CPU is the ''brain'' chip, and it goes in the socket on the motherboard.','Lift the retention lever, align the triangle, lower the CPU without force, then lock the lever.','placement',5);
INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=4),'CPU (Processor)','fa-microchip',1,'cpu_socket');
