INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=4),'CPU cooler','fa-fan',0,'later');
INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,5,'Apply thermal paste','Apply the correct amount of thermal paste on the CPU surface.','A small amount is enough.','A pea-sized dot spreads evenly under cooler pressure and improves heat transfer. Too much overflows onto the socket.','placement',5);
INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=5),'Pea-sized dot of thermal paste','fa-droplet',1,'thermal');
