INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,6,'Install the CPU cooler','Mount the cooler on the CPU and tighten evenly.','The cooler sits directly on top of the CPU.','Align the bracket, tighten screws in a cross pattern, and plug the fan into the CPU_FAN header.','placement',5);
INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=6),'CPU cooler (matching socket)','fa-fan',1,'cpu_cooler');
