INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,7,'Install RAM modules','Insert the memory module into the correct slot.','RAM goes in the long slots near the CPU.','Match the notch, then press both ends until the clips click. Use the slots recommended by the manual for dual channel.','placement',5);
INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=7),'RAM module (matching DDR type)','fa-memory',1,'ram_slots');
