INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,8,'Install the motherboard into the case','Mount the motherboard on the standoffs with the I/O shield in place.','The motherboard needs standoffs under it so it does not touch the metal tray.','Standoffs raise the board to prevent short circuits; fasten every screw hole lightly and evenly.','placement',5);
INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=8),'Motherboard on standoffs with I/O shield','fa-table-cells',1,'mb_tray');
