INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=8),'Front panel cables','fa-plug-circle-bolt',0,'later');
INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,9,'Install the power supply','Mount the PSU in the PSU bay.','The PSU bay is normally at the bottom rear of the case.','Orient the fan toward the vent, then secure with four screws.','placement',5);
