INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,10,'Install HDD or SSD storage','Mount the storage drive in the drive bay.','Drives are screwed or clipped into drive bays.','3.5 inch HDDs and 2.5 inch SSDs mount in bays (M.2 SSDs go directly on the board).','placement',5);
