INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,11,'Install the graphics card','Insert the graphics card into the top PCIe x16 slot.','It uses the longest PCIe slot.','Remove the slot covers, press the card in until the latch clicks, and screw it to the case bracket.','placement',5);
