INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,12,'Connect motherboard power cables','Connect the main power cables from the PSU to the motherboard.','Two connectors: the large main one and the CPU one.','The 24-pin ATX cable powers the board; the 4+4 / 8-pin EPS cable powers the CPU. Connectors are keyed.','cable',5);
INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=12),'24-pin ATX + 8-pin CPU power cables','fa-bolt',1,'atx_power');
