INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,13,'Connect storage cables','Connect the data and power cables for the storage drive.','Data goes to the motherboard SATA ports.','SATA data goes drive-to-motherboard; SATA power comes from the PSU.','cable',5);
INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=13),'SATA data + SATA power cables','fa-grip-lines',1,'sata_ports');
