INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=14),'Front panel connectors (PWR, RST, LED, USB, audio)','fa-plug-circle-bolt',1,'front_panel');
