INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,15,'Install cooling fans and organize cables','Mount the case fans and route cables cleanly.','Fans mount on the case''s front, top or rear.','Front/bottom fans pull air in, rear/top fans push air out. Tidy cables with ties for better airflow.','placement',5);
INSERT INTO assembly_components (step_id,label,icon,is_correct,target_zone) VALUES ((SELECT id FROM assembly_steps WHERE module_id=1 AND step_no=15),'Case fans + cable ties','fa-wind',1,'fan_mounts');
