INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,16,'Inspect all connections','Do a full visual inspection before powering on.','Check before you turn it on.','Verify seated RAM, CPU power, 24-pin, GPU power, drive cables, front-panel leads and no loose screws.','inspection',5);
