INSERT INTO assembly_steps (module_id,step_no,title,instruction,hint,explanation,step_type,points) VALUES (1,18,'Perform the initial boot test','Power on the system and confirm it passes POST and reaches BIOS/UEFI.','Press the power button and watch the POST.','A successful POST with all parts detected confirms the build. Beep codes/LEDs indicate faults.','test',5);
