INSERT INTO reviewer_topics (title,category,content,created_by) VALUES ('What is inside a desktop computer?','Computer Hardware Lessons','A desktop computer is made of several parts that work together.
INSERT INTO reviewer_topics (title,category,content,created_by) VALUES ('ESD and electrical safety','Safety Precautions','Electrostatic discharge (ESD) can silently damage components.
INSERT INTO reviewer_topics (title,category,content,created_by) VALUES ('Assembly order overview','Computer Assembly Procedures','A reliable build order is: prepare workspace and safety, install CPU, thermal paste and cooler, RAM, motherboard into the case, PSU, storage, graphics card, then cables (24-pin, CPU power, SATA, front panel), fans and cable management, final inspection, peripherals and the boot test.',1);
